public class Runner { public static void main(String[] args) { long sum=0; for(int i=0;i<=65535;i++) { int value=RequiredConversions.declared((char)i); if(value!=i || RequiredConversions.assigned((char)i)!=i || RequiredConversions.written((char)i)!=i || !RequiredConversions.castPart((char)i).equals(i+"!") || !RequiredConversions.castPartLast("x",(char)i).equals("x"+i)) throw new AssertionError("char="+i+", result="+value); sum+=value; } System.out.println("chars=65536,sum="+sum); } }
